@extends('layouts.app') @section('title','Penjualan') @section('heading','Penjualan / Stock-out') @section('content')<div class="page-actions"><p class="muted">Catat penjualan. Sistem memeriksa stok sebelum transaksi disimpan.</p><a class="btn primary" href="{{ route('sales.create') }}">＋ Buat Penjualan</a></div><div class="panel"><form class="toolbar wrap-toolbar" method="GET"><input name="q" value="{{ request('q') }}" placeholder="Cari nomor penjualan"><input type="date" name="from" value="{{ request('from') }}"><input type="date" name="to" value="{{ request('to') }}"><select name="status"><option value="">Semua status</option><option value="completed" @selected(request('status')==='completed')>Selesai</option><option value="cancelled" @selected(request('status')==='cancelled')>Dibatalkan</option></select><button class="btn secondary">Filter</button></form><div class="table-wrap"><table><thead><tr><th>NO</th><th>No. Penjualan</th><th>Tanggal</th><th>Petugas</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody>@forelse($rows as $row)<tr><td>{{ $rows->firstItem()+$loop->index }}</td><td class="code">{{ $row->sale_number }}</td><td>{{ $row->sold_at->format('d/m/Y H:i') }}</td><td>{{ $row->user->name }}</td><td class="strong">Rp {{ number_format($row->total,0,',','.') }}</td><td><span class="status {{ $row->status==='completed'?'good':'muted-status' }}">{{ $row->status==='completed'?'Selesai':'Dibatalkan' }}</span></td><td><div class="actions"><a class="btn small secondary" href="{{ route('sales.show',$row) }}">Detail</a>@if(auth()->user()->role==='admin'&&$row->status==='completed')<form method="POST" action="{{ route('sales.cancel',$row) }}" onsubmit="return confirm('Batalkan penjualan dan pulihkan stok?')">@csrf<button class="btn small danger-btn">Batalkan</button></form>@endif</div></td></tr>@empty<tr><td colspan="7" class="empty">Belum ada penjualan.</td></tr>@endforelse</tbody></table></div><div class="pagination">{{ $rows->links() }}</div></div>@en